// ZwpLinuxDmabufFeedbackV1 is a client side proxy for zwp_linux_dmabuf_feedback_v1.
// This object advertises dmabuf parameters feedback. This includes the
// preferred devices and the supported formats/modifiers. The parameters are
// sent once when this object is created and whenever they change. The done
// event is always sent once after all parameters have been sent. When a
// single parameter changes, all parameters are re-sent by the compositor.
// Compositors can re-send the parameters when the current client buffer
// allocations are sub-optimal. Compositors should not re-send the parameters
// if re-allocating the buffers would not result in a more optimal
// configuration. In particular, compositors should avoid sending the exact
// same parameters multiple times in a row. The tranche_target_device and
// tranche_formats events are grouped by tranches of preference. For each
// tranche, a tranche_target_device, one tranche_flags and one or more
// tranche_formats events are sent, followed by a tranche_done event
// finishing the list. The tranches are sent in descending order of
// preference. All formats and modifiers in the same tranche have the same
// preference. To send parameters, the compositor sends one main_device event
// (unless the client bound version 6 or above), tranches (each consisting of
// one tranche_target_device event, one tranche_flags event, tranche_formats
// events and then a tranche_done event), then one done event. With version 6
// and above, the compositor must always advertise at least one tranche with
// the sampling flag set. The compositor sends a format_table event at least
// once for each dmabuf parameters feedback object, before any tranche
// events. Unless the format table contents change later, the compositor is
// free not to send another format_table event for the same dmabuf parameters
// feedback object.
pub struct ZwpLinuxDmabufFeedbackV1 {
	wayland.Object
}

// zwp_linux_dmabuf_feedback_v1_proxy wraps an object id in a ZwpLinuxDmabufFeedbackV1 proxy.
pub fn zwp_linux_dmabuf_feedback_v1_proxy(conn &wayland.Connection, id u32) ZwpLinuxDmabufFeedbackV1 {
	return ZwpLinuxDmabufFeedbackV1{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'zwp_linux_dmabuf_feedback_v1'
		}
	}
}

// ZwpLinuxDmabufFeedbackV1Listener receives the events of a zwp_linux_dmabuf_feedback_v1 object.
pub interface ZwpLinuxDmabufFeedbackV1Listener {
	// This event is sent after all parameters of a zwp_linux_dmabuf_feedback_v1
	// object have been sent. This allows changes to the
	// zwp_linux_dmabuf_feedback_v1 parameters to be seen as atomic, even if they
	// happen via multiple events.
mut:
	done(proxy ZwpLinuxDmabufFeedbackV1)
	// This event provides a file descriptor which can be memory-mapped to access
	// the format and modifier table. The table contains a tightly packed array
	// of consecutive format + modifier pairs. Each pair is 16 bytes wide. It
	// contains a format as a 32-bit unsigned integer, followed by 4 bytes of
	// unused padding, and a modifier as a 64-bit unsigned integer. The native
	// endianness is used. The client must map the file descriptor in read-only
	// private mode. Compositors are not allowed to mutate the table file
	// contents once this event has been sent. Instead, compositors must create a
	// new, separate table file and re-send feedback parameters. Compositors are
	// allowed to store duplicate format + modifier pairs in the table.
	format_table(proxy ZwpLinuxDmabufFeedbackV1, fd int, size u32)
	// This event advertises the main device that the server prefers to use when
	// direct scan-out to the target device isn't possible. The advertised main
	// device may be different for each zwp_linux_dmabuf_feedback_v1 object, and
	// may change over time. There is exactly one main device. The compositor
	// must send at least one preference tranche with tranche_target_device equal
	// to main_device. Clients need to create buffers that the main device can
	// import and read from, otherwise creating the dmabuf wl_buffer will fail
	// (see the zwp_linux_buffer_params_v1.create and create_immed requests for
	// details). The main device will also likely be kept active by the
	// compositor, so clients can use it instead of waking up another device for
	// power savings. In general the device is a DRM node. The DRM node type
	// (primary vs. render) is unspecified. Clients must not rely on the
	// compositor sending a particular node type. Clients cannot check two
	// devices for equality by comparing the dev_t value. If explicit modifiers
	// are not supported and the client performs buffer allocations on a
	// different device than the main device, then the client must force the
	// buffer to have a linear layout. With version 6 and above, this event is no
	// longer sent. Clients should use a device with the sampling flag in the
	// tranches instead.
	main_device(proxy ZwpLinuxDmabufFeedbackV1, device []u8)
	// This event splits tranche_target_device and tranche_formats events into
	// preference tranches. It is sent after a set of tranche_target_device and
	// tranche_formats events; it represents the end of a tranche. The next
	// tranche will have a lower preference.
	tranche_done(proxy ZwpLinuxDmabufFeedbackV1)
	// This event advertises the target device that the server prefers to use for
	// a buffer created given this tranche. The advertised target device may be
	// different for each preference tranche, and may change over time. There is
	// exactly one target device per tranche. The target device may be a scan-out
	// device, for example if the compositor prefers to directly scan-out a
	// buffer created given this tranche. The target device may be a rendering
	// device, for example if the compositor prefers to texture from said buffer.
	// The client can use this hint to allocate the buffer in a way that makes it
	// accessible from the target device, ideally directly. The buffer must still
	// be accessible from a device with the sampling flag, either through direct
	// import or a potentially more expensive fallback path. If the buffer can't
	// be directly imported for sampling, then clients must be prepared for the
	// compositor changing the tranche priority or making wl_buffer creation fail
	// (see the zwp_linux_buffer_params_v1.create and create_immed requests for
	// details). If the device is a DRM node, the DRM node type (primary vs.
	// render) is unspecified. Clients must not rely on the compositor sending a
	// particular node type. Clients cannot check two devices for equality by
	// comparing the dev_t value. This event is tied to a preference tranche, see
	// the tranche_done event.
	tranche_target_device(proxy ZwpLinuxDmabufFeedbackV1, device []u8)
	// This event advertises the format + modifier combinations that the
	// compositor supports. It carries an array of indices, each referring to a
	// format + modifier pair in the last received format table (see the
	// format_table event). Each index is a 16-bit unsigned integer in native
	// endianness. For legacy support, DRM_FORMAT_MOD_INVALID is an allowed
	// modifier. It indicates that the server can support the format with an
	// implicit modifier. When a buffer has DRM_FORMAT_MOD_INVALID as its
	// modifier, it is as if no explicit modifier is specified. The effective
	// modifier will be derived from the dmabuf. A compositor that sends valid
	// modifiers and DRM_FORMAT_MOD_INVALID for a given format supports both
	// explicit modifiers and implicit modifiers. Compositors must not send
	// duplicate format + modifier pairs within the same tranche or across two
	// different tranches with the same target device and flags. This event is
	// tied to a preference tranche, see the tranche_done event. For the
	// definition of the format and modifier codes, see the
	// zwp_linux_buffer_params_v1.create request.
	tranche_formats(proxy ZwpLinuxDmabufFeedbackV1, indices []u8)
	// This event sets tranche-specific flags. This event is tied to a preference
	// tranche, see the tranche_done event. With version 6 and above, the
	// compositor must set at least one flag in each tranche.
	tranche_flags(proxy ZwpLinuxDmabufFeedbackV1, flags u32)
}

// NoopZwpLinuxDmabufFeedbackV1Listener ignores every zwp_linux_dmabuf_feedback_v1 event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopZwpLinuxDmabufFeedbackV1Listener {}

pub fn (mut listener NoopZwpLinuxDmabufFeedbackV1Listener) done(_proxy ZwpLinuxDmabufFeedbackV1) {
}

pub fn (mut listener NoopZwpLinuxDmabufFeedbackV1Listener) format_table(_proxy ZwpLinuxDmabufFeedbackV1, _fd int, _size u32) {
}

pub fn (mut listener NoopZwpLinuxDmabufFeedbackV1Listener) main_device(_proxy ZwpLinuxDmabufFeedbackV1, _device []u8) {
}

pub fn (mut listener NoopZwpLinuxDmabufFeedbackV1Listener) tranche_done(_proxy ZwpLinuxDmabufFeedbackV1) {
}

pub fn (mut listener NoopZwpLinuxDmabufFeedbackV1Listener) tranche_target_device(_proxy ZwpLinuxDmabufFeedbackV1, _device []u8) {
}

pub fn (mut listener NoopZwpLinuxDmabufFeedbackV1Listener) tranche_formats(_proxy ZwpLinuxDmabufFeedbackV1, _indices []u8) {
}

pub fn (mut listener NoopZwpLinuxDmabufFeedbackV1Listener) tranche_flags(_proxy ZwpLinuxDmabufFeedbackV1, _flags u32) {
}

struct ZwpLinuxDmabufFeedbackV1Sink {
mut:
	proxy    ZwpLinuxDmabufFeedbackV1
	listener ZwpLinuxDmabufFeedbackV1Listener = NoopZwpLinuxDmabufFeedbackV1Listener{}
}

fn (mut s ZwpLinuxDmabufFeedbackV1Sink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			s.listener.done(s.proxy)
		}
		1 {
			fd := msg.arg_fd(0)!
			size := msg.arg_u32(1)!
			s.listener.format_table(s.proxy, fd, size)
		}
		2 {
			device := msg.arg_array(0)!
			s.listener.main_device(s.proxy, device)
		}
		3 {
			s.listener.tranche_done(s.proxy)
		}
		4 {
			device := msg.arg_array(0)!
			s.listener.tranche_target_device(s.proxy, device)
		}
		5 {
			indices := msg.arg_array(0)!
			s.listener.tranche_formats(s.proxy, indices)
		}
		6 {
			flags := msg.arg_u32(0)!
			s.listener.tranche_flags(s.proxy, flags)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives zwp_linux_dmabuf_feedback_v1 events.
pub fn (proxy &ZwpLinuxDmabufFeedbackV1) set_listener(listener ZwpLinuxDmabufFeedbackV1Listener) ! {
	proxy.conn.set_sink(proxy.id, ZwpLinuxDmabufFeedbackV1Sink{
		proxy:    *proxy
		listener: listener
	})!
}

