pub fn bind_zwp_linux_dmabuf_v1(conn &wayland.Connection, global wayland.Global) !ZwpLinuxDmabufV1 {
	version := if global.version < zwp_linux_dmabuf_v1_desc.version {
		global.version
	} else {
		zwp_linux_dmabuf_v1_desc.version
	}
	object := conn.bind_global(global, 'zwp_linux_dmabuf_v1', version, &zwp_linux_dmabuf_v1_desc)!
	return ZwpLinuxDmabufV1{
		Object: object
	}
}
